import {operationDate,currentTimeZone,setTimeZone,validTimeZone} from './time.mjs';
import {id,money,DEMO_DATE,escapeHtml as esc} from './core.mjs';
import {parseBRL,validDate} from './finance.mjs';
import {createPaymentDocumentPdf} from './pdf.mjs';

export const RECEIPTS_FOLDER='Recibos e comprovantes';
const TYPES={receipt:'Rascunho de recibo',payment_record:'Registro de pagamento'};
const METHODS={unspecified:'Não informar',pix:'Pix',cash:'Dinheiro',debit:'Débito',boleto:'Boleto',transfer:'Transferência',other:'Outro'};
const dateLabel=value=>value.split('-').reverse().join('/');
const bytesToBase64=bytes=>{let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary);};
export const isReceiptDocument=doc=>doc.folder==='receipts'||doc.category===RECEIPTS_FOLDER||doc.kind==='receipt_draft';
export function validatePaymentDocument(state,raw){
 const draft={documentType:raw.documentType,payer:String(raw.payer||'').trim(),payee:String(raw.payee||'').trim(),title:String(raw.title||'').trim(),cents:parseBRL(raw.amount),date:raw.date,paymentMethod:raw.paymentMethod||'unspecified',note:String(raw.note||'').trim(),recordId:raw.recordId||null};
 const errors=[];
 if(!TYPES[draft.documentType])errors.push('Escolha o tipo de documento.');
 for(const [key,label,max] of [['payer','quem pagou',100],['payee','quem recebeu',100],['title','o motivo',200]])if(!draft[key]||draft[key].length>max)errors.push(`Preencha ${label} com até ${max} caracteres.`);
 if(draft.cents===null)errors.push('Informe um valor positivo, como 130,00.');
 if(!validDate(draft.date))errors.push('Escolha uma data válida.');
 if(!METHODS[draft.paymentMethod])errors.push('Escolha uma forma de pagamento válida.');
 if(draft.note.length>300)errors.push('A observação pode ter até 300 caracteres.');
 if(draft.recordId&&!state.records.some(r=>r.id===draft.recordId&&r.type!=='transfer'&&r.status==='actual'))errors.push('Escolha um lançamento realizado existente ou deixe sem vínculo.');
 draft.methodLabel=draft.paymentMethod==='unspecified'?'Não informada':METHODS[draft.paymentMethod];return {ok:!errors.length,errors,draft};
}
export function createIndependentDocument(state,raw,documentId=id()){
 const result=validatePaymentDocument(state,raw);if(!result.ok)return {...result,state};
 const existing=state.documents.find(d=>d.id===documentId);if(existing)return {ok:true,state,document:existing,duplicate:true};
 const payload=structuredClone(result.draft),bytes=createPaymentDocumentPdf(payload);
 const document={id:documentId,title:`${TYPES[payload.documentType]} · ${payload.title}`,category:RECEIPTS_FOLDER,folder:'receipts',date:payload.date,createdAt:new Date().toISOString(),note:'Documento próprio, com dados informados e assinatura em branco. Não fiscal; sem validação bancária ou de quitação.',ext:'PDF',mime:'application/pdf',trashed:false,kind:'standalone_payment',documentType:payload.documentType,recordId:payload.recordId,payload,pdfData:bytesToBase64(bytes),fileSize:bytes.length};
 return {ok:true,state:{...state,documents:[document,...state.documents]},document};
}
export function paymentDocumentBytes(doc){return doc.pdfData?Uint8Array.from(atob(doc.pdfData),c=>c.charCodeAt(0)):createPaymentDocumentPdf(doc.payload);}

export function createDocumentsUI(ctx){
 const {getState,setState,save,toast,modal,closeModal,render,icon,button,link,field,selectField,download,goToFolder}=ctx;
 let draft={documentType:'receipt',payer:'',payee:'',title:'',amount:'',date:operationDate(),paymentMethod:'unspecified',note:'',recordId:''},pending=null,sharing=false;
 const fail=message=>{const node=document.querySelector('#document-error');if(node)node.textContent=message;else toast(message);};
 const copy=(demo,live)=>globalThis.mentraProduction?live:demo;
 const fields=()=>`${selectField('O que você quer criar?','documentType',[['receipt','Recibo de pagamento · rascunho'],['payment_record','Comprovante próprio · registro de pagamento']],draft.documentType)}<div class="form-grid"><div>${field('Quem pagou','payer',draft.payer,'text',copy('required maxlength="100" placeholder="Nome fictício"','required maxlength="100" placeholder="Nome informado"'))}</div><div>${field('Quem recebeu','payee',draft.payee,'text',copy('required maxlength="100" placeholder="Nome fictício"','required maxlength="100" placeholder="Nome informado"'))}</div></div><div class="form-grid"><div>${field('Valor informado (R$)','amount',draft.amount,'text','required inputmode="decimal" maxlength="20" placeholder="130,00"')}</div><div>${field('Data do pagamento informado','date',draft.date,'date','required')}</div></div>${field('Referente a / motivo','title',draft.title,'text','required maxlength="200" placeholder="Ex.: serviço de organização"')}${selectField('Forma de pagamento (opcional)','paymentMethod',Object.entries(METHODS),draft.paymentMethod)}<label for="document-note">Observação (opcional)</label><textarea id="document-note" name="note" maxlength="300" rows="3">${esc(draft.note)}</textarea><details class="document-optional"><summary>Vincular a um lançamento existente (opcional)</summary><label for="document-record">Apenas uma referência, sem alterar valores</label><select id="document-record" name="recordId"><option value="">Sem vínculo com lançamento</option>${getState().records.filter(r=>r.type!=='transfer'&&r.status==='actual').map(r=>`<option value="${esc(r.id)}" ${r.id===draft.recordId?'selected':''}>${esc(r.title)} · ${money(r.cents)}</option>`).join('')}</select></details>`;
 function renderCreate({showHeading=true}={}){return `${showHeading?`<div class="document-create-heading"><div><span class="eyebrow">PARA GUARDAR OU ENTREGAR A ALGUÉM</span><h2>Criar recibo ou comprovante</h2><p>Um documento específico, do seu jeito. Você não precisa cadastrar um gasto para criá-lo.</p></div>${link('Voltar aos documentos','vida/documentos','outline')}</div>`:''}<div class="document-create-layout"><section class="card document-create-card"><form id="payment-document-form">${fields()}<p id="document-error" class="form-error" role="alert"></p><div class="document-form-actions">${link('Cancelar','vida/documentos','outline')}<button class="primary" type="submit">Revisar documento ${icon('arrow')}</button></div></form></section><aside class="stack"><section class="card tinted"><span class="round-icon">${icon('lock')}</span><h3>Já vai para a pasta certa.</h3><p>Ao confirmar, o PDF fica em <b>Documentos → Recibos e comprovantes</b>. Depois, você pode baixar, imprimir ou abrir o compartilhamento do dispositivo.</p>${link('Ver minha pasta '+icon('arrow'),'vida/documentos/recibos')}</section><div class="notice warm">${copy('Use dados fictícios nesta demonstração. O documento é próprio,','O documento é próprio,')} não fiscal e não é um comprovante emitido por banco. A assinatura de quem recebeu fica em branco.</div><div class="notice subtle">Criar o documento não cria nem altera lançamentos, saldos ou pagamentos. ${copy('Tudo fica somente neste navegador, sem backup na nuvem.','Os documentos são sincronizados com sua conta; você também pode exportar uma cópia.')}</div></aside></div>`;}
 function preview(payload){const values=[['Documento',TYPES[payload.documentType]],['Quem pagou',payload.payer],['Quem recebeu',payload.payee],['Valor informado',money(payload.cents)],['Data',dateLabel(payload.date)],['Referente a',payload.title],['Forma',payload.methodLabel],...(payload.note?[['Observação',payload.note]]:[]),['Vínculo',payload.recordId?getState().records.find(r=>r.id===payload.recordId)?.title||'Lançamento':'Nenhum lançamento'],['Assinatura','Linha em branco para quem recebeu']];return `<div class="document-preview"><span class="eyebrow">PRÉVIA DOS DADOS</span><div class="review-details">${values.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><div class="signature-preview">Assinatura de quem recebeu</div></div>`;}
 function handleSubmit(form){if(form.id!=='payment-document-form')return false;if(!form.checkValidity()){form.reportValidity();return true;}draft=Object.fromEntries(new FormData(form));const checked=validatePaymentDocument(getState(),draft);if(!checked.ok){fail(checked.errors.join(' '));return true;}pending={raw:structuredClone(draft),payload:checked.draft,id:id()};modal('Confira seu documento',`${preview(checked.draft)}<p class="small muted">${copy('Será salvo em Documentos → Recibos e comprovantes, somente neste navegador.','Será guardado em Documentos → Recibos e comprovantes na sua conta.')} Sem emissão fiscal, validação de assinatura ou confirmação automática de quitação.</p><p id="document-error" class="form-error" role="alert"></p><div class="modal-actions">${button('Voltar e editar','document-back','outline')}${button('Confirmar e salvar PDF','document-confirm','primary')}</div>`);return true;}
 function confirm(){if(!pending)return;const p=pending;let result;try{result=createIndependentDocument(getState(),p.raw,p.id);}catch{fail('Não foi possível gerar o PDF. Revise os campos e tente novamente.');return;}if(!result.ok){fail(result.errors.join(' '));return;}const before=getState();setState(result.state);if(save()===false){setState(before);fail('Não foi possível guardar o PDF neste navegador. Libere espaço ou exporte seus exemplos antes de tentar novamente. Nada foi salvo.');return;}pending=null;draft={documentType:'receipt',payer:'',payee:'',title:'',amount:'',date:operationDate(),paymentMethod:'unspecified',note:'',recordId:''};closeModal();goToFolder();toast('PDF salvo em Recibos e comprovantes. Nenhum lançamento foi criado.');}
 const filename=doc=>`${doc.documentType==='receipt'?'rascunho-recibo':'registro-pagamento'}-${doc.date}-${doc.id.slice(0,8)}.pdf`;
 function downloadDoc(doc){download(filename(doc),paymentDocumentBytes(doc),'application/pdf');}
 function openDocument(documentId){const doc=getState().documents.find(d=>d.id===documentId&&!d.trashed);if(doc?.kind!=='standalone_payment')return false;modal(esc(TYPES[doc.documentType]||'Documento'),`${preview(doc.payload)}<p class="small muted">Salvo em Documentos → Recibos e comprovantes. Este PDF preserva os dados confirmados na criação.</p><div class="entry-document-actions">${button('Baixar PDF','document-download','primary',`data-id="${esc(doc.id)}"`)}${button('Abrir PDF para imprimir','document-print','outline',`data-id="${esc(doc.id)}"`)}${button('Compartilhar PDF…','document-share','outline',`data-id="${esc(doc.id)}"`)}</div><p class="small muted">Você escolhe a pessoa e confirma no compartilhamento do dispositivo. Se ele não estiver disponível, baixe o PDF para enviar por conta própria.</p><div class="notice warm">Documento próprio não fiscal, sem assinatura capturada. Não é comprovante bancário e não confirma automaticamente pagamento ou quitação.</div>`);return true;}
 async function shareDoc(doc){if(sharing)return;let file;try{file=new File([paymentDocumentBytes(doc)],filename(doc),{type:'application/pdf'});if(!navigator.share||!navigator.canShare?.({files:[file]}))throw new Error('unavailable');}catch{toast('Compartilhamento de arquivos indisponível. Use Baixar PDF e envie pelo aplicativo que preferir.');return;}sharing=true;try{await navigator.share({files:[file],title:TYPES[doc.documentType]});toast('O documento foi entregue ao compartilhamento do dispositivo. A Mentra não confirma o envio ao destinatário.');}catch(error){toast(error.name==='AbortError'?'Compartilhamento cancelado ou sem destino disponível. Seu PDF continua na pasta.':'Não foi possível abrir o compartilhamento. Use Baixar PDF.');}finally{sharing=false;}}
 function handleClick(action,data){if(!action.startsWith('document-'))return false;if(action==='document-confirm')confirm();else if(action==='document-back'){pending=null;closeModal();render();}else{const doc=getState().documents.find(d=>d.id===data.id&&!d.trashed);if(doc?.kind!=='standalone_payment')return true;if(action==='document-download')downloadDoc(doc);else if(action==='document-share')void shareDoc(doc);else if(action==='document-print'){const url=URL.createObjectURL(new Blob([paymentDocumentBytes(doc)],{type:'application/pdf'}));const popup=window.open(url,'_blank');if(popup)popup.opener=null;else{downloadDoc(doc);toast('A nova aba foi bloqueada. O PDF foi baixado para imprimir.');}setTimeout(()=>URL.revokeObjectURL(url),60000);}}return true;}
 return {renderCreate,handleSubmit,handleClick,openDocument,cancelPending:()=>{pending=null;}};
}
